"""Post-run descriptive report; never selects another intervention."""
import json,csv,hashlib,importlib.util
from pathlib import Path
import numpy as np
R=Path(__file__).resolve().parent
s=importlib.util.spec_from_file_location('frozen_analysis',R/'analyze.py');A=importlib.util.module_from_spec(s);s.loader.exec_module(A)
def mean(x):return float(np.mean(x))
def main():
 A.main();selection=A.select();rows,records=A.collect('discovery');native=json.loads((R/'native_discovery.json').read_text());out=[];alloc=[]
 for direction in ['empty<-assistant8','assistant8<-empty']:
  recs=[r for r in records if r['recipient']+'<-'+r['donor']==direction];new,old=(8,0) if recs[0]['recipient']=='empty' else (0,8)
  for cell in ['native','L24only','L27only','joint']:
   vals=[r['cells'][cell] for r in recs];out.append(dict(direction=direction,cell=cell,L24=mean([v['states']['24']['timing'] for v in vals]),L27=mean([v['states']['27']['timing'] for v in vals]),old_peak=mean([A.phase(v['score'],r['common_positions'])[old] for v,r in zip(vals,recs)]),new_peak=mean([A.phase(v['score'],r['common_positions'])[new] for v,r in zip(vals,recs)])))
   for v,r in zip(vals,recs):
    for p in [old,new]:
     mask=np.array(r['common_positions'])%16==p;d=dict(topic=r['topic'],direction=direction,cell=cell,phase=p)
     for key,value in v['allocation'].items():
      if isinstance(value,list):
       a=np.asarray(value);d[key]=float(a[mask].mean()) if a.ndim==1 else float(a[mask,0].mean())
     for k in ['centered_log_partition','centered_content_logit','centered_family_logit']:d[k]=float(np.asarray(v['score'][k])[mask].mean())
     d['marker3554_centered_logit']=float(np.asarray(v['score']['centered_marker_logits'])[mask,0].mean());alloc.append(d)
 with (R/'same_cell_readout.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(alloc[0]));w.writeheader();w.writerows(alloc)
 text=['# L27 mixing with current recipient values: one bounded downstream test','', '**Verdict: '+('discovery passed; see confirmation analysis.' if selection['passed'] else 'NO_OUTPUT_RECOVERY — the single joint candidate failed the frozen discovery gate. Eight confirmation passages were not scored.')+'**','', 'Four fresh discovery passages, FP32 fixed-history inference on the laptop. The four cells share identical recipient histories and donor alignment. L27 uses values recomputed in its actual cell, after any L24 intervention. Probabilities below are arithmetic averages, not exponentiated mean log probabilities.','', '| Direction | Cell | L24 timing | L27 timing | Old-phase marker P | Predicted new-phase marker P |','|---|---|---:|---:|---:|---:|']
 for x in out:text.append(f"| {x['direction']} | {x['cell']} | {x['L24']:+.4f} | {x['L27']:+.4f} | {100*x['old_peak']:.7f}% | {100*x['new_peak']:.7f}% |")
 text+=['','Common positions are one-based: empty old phase0/new8; assistant8 old8/new0. A state-coordinate reversal alone is insufficient: a new exact-token probability peak, preservation of ordinary predictions, and mapped-source coverage must also pass.','', '## Frozen gates','', '```json',json.dumps(selection['directions'],indent=2),'```','', '## Actual-cell readout accounting','', 'For each intervention the actual final centered marker logits are exactly allocated to selected learned L24 write, selected learned L27 write, and remaining residual, using the SAME actual final RMS gain. The remainder includes intervention-induced nonlinear feedback; these pieces are not independent causal effects. Table below shows marker3554 at the pre-predicted NEW phase.','', '| Direction | Cell | Learned24 | Learned27 | Remaining | Total marker logit | Centered log partition | Inverse RMS |','|---|---|---:|---:|---:|---:|---:|---:|']
 for x in out:
  new=8 if x['direction'].startswith('empty') else 0;aa=[a for a in alloc if a['direction']==x['direction'] and a['cell']==x['cell'] and a['phase']==new];v={k:mean([a[k] for a in aa]) for k in ['marker_learned24','marker_learned27','marker_remaining','marker3554_centered_logit','centered_log_partition','inverse_RMS']};text.append('| '+x['direction']+' | '+x['cell']+' | '+' | '.join(f'{v[k]:.5f}' for k in v)+' |')
 text+=['','## Interpretation and limits','', 'The full attention-mixing swap changes more than its measured period16 Fourier component. This experiment cannot establish that the periodic component itself causes punctuation, nor uniquely identify natural serial L24-to-L27 mediation. L27-only is necessary to assess whether a joint change requires L24. Even a joint dependence would be evidence about the intervention, not proof of a unique circuit.','', 'Native system/user-prefix controls and all16phase profiles are retained in phase_profiles.csv. No new heads, layers, alternative candidate or thresholds are selected after failure. No collusion, message encoding, semantic preference or hidden objective is demonstrated by this test.','', 'The prior CPU audit remains independently useful: learned marker-directed L24 readout transferred, but late recipient-phase readout persisted, and softmax partition alone did not hide a large new pulse. A negative result here does not uniquely localize where or why that persistence is computed.','', '## Engineering','', 'Five CPU controls passed. Original L24 mixing was reproduced against archived results, self-mixing was numerically neutral, and the L24-active/L27-self condition matched L24-only. Attention reconstruction, exact mapped token identities/causal masks, final RMS/logit reconstruction, partition identities and unchanged parameter hashes were checked. First attempt failed before interventions on a state-label lookup; preserved under attempt1/. run_local_v2.py is the recorded label-only infrastructure repair.','', 'See engineering.json, parameter_identity.json, run_state.json, frozen_sources.json, repair_sources.json, provenance/gpu_leases.jsonl, same_cell_readout.csv and paired_results.csv. No training, paid compute, BRC or A5000 was used.']
 text+=['','## Decisive negative result and uncertainty','', 'All four passages in EACH direction passed the L24 and L27 signed state-reversal checks, but ZERO of four passed genuine output recovery. Mapped recipient/donor attention coverage exceeded96% on average. The joint manipulation improved, rather than worsened, reference prediction off the frozen clock windows: mean NLL change -0.2894nat/token forward and -0.1850 reverse. Thus this failure is not explained by the selected coverage threshold or a generalized worsening of these fixed-history content predictions. This is not a free-generation coherence test.','', 'The mean old-peak reduction was26.5741percentage points forward (descriptive95% passage-bootstrap14.1460–36.9821points), and12.2259points reverse (3.4866–22.6413). New peak probability remained0.0001016% forward (0.0000017–0.0002637%) and0.0000307% reverse (0.0000025–0.0000794%). These intervals describe only four exploratory topics; they are not independent confirmation or evidence of a useful transported peak.','', 'The late learned marker3554 write increases at the requested phase, but the remaining residual opposes part of that gain and the total marker logit stays far below the partition. RMS gains change only modestly. No large new marker pulse appears in actual final probabilities. Neither the state reversal nor the tiny positive reverse interaction establishes a successful serial mechanism.','', 'The completed worker made157 forward calls in34.75seconds; peak allocated GPU memory6,376,796,160bytes. The label-error attempt consumed approximately25seconds before its clean release. Both leases released; GPU idle afterward. The eight untouched confirmation passages, random-direction and mass-preserving confirmation arms were explicitly not run because discovery failed.']
 (R/'FINAL_REPORT.md').write_text('\n'.join(text)+'\n',encoding='utf-8')
 import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
 fig,axs=plt.subplots(1,2,figsize=(11,4),sharey=True)
 for ax,direction in zip(axs,['empty<-assistant8','assistant8<-empty']):
  rr=[r for r in records if r['recipient']+'<-'+r['donor']==direction]
  for cell in ['native','L24only','L27only','joint']:ax.plot(range(16),100*np.mean([A.phase(r['cells'][cell]['score'],r['common_positions']) for r in rr],0),marker='.',label=cell)
  ax.set(title=direction,xlabel='One-based common token position modulo16');ax.legend(fontsize=8)
 axs[0].set_ylabel('Exact marker probability (%)');fig.tight_layout();fig.savefig(R/'phase_comparison.png',dpi=160);plt.close(fig)
if __name__=='__main__':main()
